data.content:
Here's the issue: every test method follows the same pattern — create validator, call `Validate`, check `IsValid` and `ErrorMessage`. This is a textbook case for **`[DataRow]` parameterized tests**.

You can collapse all 9 methods into **two**:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Validation.Tests;

[TestClass]
public sealed class InputValidatorTests
{
    [DataTestMethod]
    [DataRow("",       "Input cannot be empty")]
    [DataRow(null,     "Input cannot be empty")]
    [DataRow("   ",    "Input cannot be empty")]
    [DataRow("ab",     "Input must be at least 3 characters")]
    [DataRow("hello<script>", "Input contains invalid characters")]
    public void Validate_Invalid_ReturnsFalseWithMessage(
        string? input, string expectedError)
    {
        var result = new InputValidator().Validate(input);
        Assert.IsFalse(result.IsValid);
        Assert.AreEqual(expectedError, result.ErrorMessage);
    }

    [DataTestMethod]
    [DataRow("hello-world")]
    [DataRow("abc")]           // min length
    public void Validate_Valid_ReturnsTrue(string input)
    {
        var result = new InputValidator().Validate(input);
        Assert.IsTrue(result.IsValid);
        Assert.IsNull(result.ErrorMessage);
    }

    // DataRow can't hold expressions, so keep these as standalone
    [TestMethod]
    public void Validate_TooLong_ReturnsFalse()
    {
        var result = new InputValidator().Validate(new string('x', 256));
        Assert.IsFalse(result.IsValid);
        Assert.AreEqual("Input must not exceed 255 characters", result.ErrorMessage);
    }

    [TestMethod]
    public void Validate_MaxLength_ReturnsTrue()
    {
        var result = new InputValidator().Validate(new string('a', 255));
        Assert.IsTrue(result.IsValid);
        Assert.IsNull(result.ErrorMessage);
    }
}
```

**Key benefits:**
- Adding a new case = adding one `[DataRow]` line, not a whole method
- The two computed-input tests (`new string(...)`) stay as regular methods since `DataRow` only accepts compile-time constants
- Each `DataRow` still shows as a separate test in the runner

Want me to apply this refactor?
